  8 | module addr_region_decode (
  9 |     input      [8:0] N,
 10 |     output     [1:0] region,
 11 |     output           valid
 12 | );
 13 |     assign region =
 14 |         (N <= 9'd79)  ? 2'd0 :
 15 |         (N <= 9'd155) ? 2'd1 :
 16 |         (N <= 9'd215) ? 2'd2 : 2'd3;
 17 | 
 18 |     assign valid = (N <= 9'd295);
