 22 | module addr_region0_calc (
 23 |     input      [8:0] N,
 24 |     output     [3:0] row,
 25 |     output     [4:0] col
 26 | );
 27 |     wire [7:0] col_full;
 28 | 
 29 |     assign row      = N[1:0];
 30 |     assign col_full =
 31 |         (8'd76 + {8'd0,N[1:0]} - {8'd0,N[7:0]}) >> 2;
