 36 | module addr_region1_calc (
 37 |     input      [8:0] N,
 38 |     output     [3:0] row,
 39 |     output     [4:0] col
 40 | );
 41 |     wire [8:0] col_full;
 42 | 
 43 |     assign row      = 4'd4 + N[1:0];
 44 |     assign col_full =
 45 |         (9'd152 + {5'd0,N[1:0]} - {9'd0,N[7:0]}) >> 2;
 46 |     assign col      = col_full[4:0];
 47 | endmodule
