 50 | module addr_region2_calc (
 51 |     input      [8:0] N,
 52 |     output     [3:0] row,
 53 |     output     [4:0] col
 54 | );
 55 |     wire [8:0]  M;
 56 |     wire [13:0] Pq;
 57 |     wire [6:0]  q2;
 58 |     wire [2:0]  r2;
 59 |     wire [3:0]  row2;
 60 |     wire [6:0]  V2;
 61 |     wire [13:0] pc;
 62 | 
 63 |     assign M  = N - 9'd148;
 64 |     assign Pq = {5'd0,M} * 9'd171;
 65 |     assign q2 = Pq >> 9;
 66 |     assign r2 = M - {5'd0,q2} * 3'd3;
 67 | 
 68 |     assign row2 = (r2 == 3'd0) ? 4'd9 :
 69 |                   (r2 == 3'd1) ? 4'd10 : 4'd8;
 70 | 
 71 |     assign V2  = M - {2'b0,row2};
 72 |     assign pc  = {5'd0,V2} * 9'd171;
 73 |     assign row = row2;
 74 |     assign col = pc[13:9];
 75 | endmodule
