 78 | module addr_region3_calc (
 79 |     input      [8:0] N,
 80 |     output     [3:0] row,
 81 |     output     [4:0] col
 82 | );
 83 |     wire [8:0] D;
 84 |     wire [1:0] m4;
 85 |     wire [3:0] row3;
 86 | 
 87 |     assign D  = N - 9'd205;
 88 |     assign m4 = D[1:0];
 89 | 
 90 |     assign row3 = (m4 == 2'd0) ? 4'd12 :
 91 |                   (m4 == 2'd1) ? 4'd13 :
 92 |                   (m4 == 2'd2) ? 4'd14 : 4'd11;
 93 | 
 94 |     assign row = row3;
 95 |     assign col = (D - {2'b0,row3}) >> 2;
 96 | endmodule
