 99 | module addr_rowcol_mux (
100 |     input      [1:0] region,
101 |     input      [3:0] row0,
102 |     input      [4:0] col0,
103 |     input      [3:0] row1,
104 |     input      [4:0] col1,
105 |     input      [3:0] row2,
106 |     input      [4:0] col2,
107 |     input      [3:0] row3,
108 |     input      [4:0] col3,
109 |     output reg [3:0] row,
110 |     output reg [4:0] col
111 | );
